#!/usr/bin/env bash
#
# Remove the systemd units installed by deploy/install.sh.
#
# Usage (on the Raspberry Pi, from the repository root):
#   sudo ./deploy/uninstall.sh
#
# The SearXNG settings under SEARXNG_CONFIG_DIR (default /etc/searxng) are kept
# unless REMOVE_CONFIG=true is set. Even then, only the settings.yml generated by
# install.sh (marked with .installed-by-smart-speaker) is removed; a reused
# directory or pre-existing settings.yml is never deleted.

set -euo pipefail

SYSTEMD_DIR="/etc/systemd/system"
SEARXNG_CONFIG_DIR="${SEARXNG_CONFIG_DIR:-/etc/searxng}"
REMOVE_CONFIG="${REMOVE_CONFIG:-false}"

info() { echo "==> $*"; }

[ "$(id -u)" -eq 0 ] || { echo "ERROR: root privileges are required" >&2; exit 1; }

for unit in smart-speaker.service searxng.service; do
    info "disabling ${unit}"
    systemctl disable --now "${unit}" >/dev/null 2>&1 || true
    rm -f "${SYSTEMD_DIR}/${unit}"
done

systemctl daemon-reload

if [ "${REMOVE_CONFIG}" = "true" ]; then
    marker="${SEARXNG_CONFIG_DIR}/.installed-by-smart-speaker"
    if [ -f "${marker}" ]; then
        info "removing generated ${SEARXNG_CONFIG_DIR}/settings.yml"
        rm -f "${SEARXNG_CONFIG_DIR}/settings.yml" "${marker}"
        # Remove the directory only if nothing else is left in it.
        rmdir "${SEARXNG_CONFIG_DIR}" 2>/dev/null || info "keeping ${SEARXNG_CONFIG_DIR} (not empty)"
    else
        info "${SEARXNG_CONFIG_DIR} was not generated by install.sh; keeping it"
    fi
fi

info "done"
